// Human-facing release number — bump this by hand, shown to customers in Settings.
// Scheme is MAJOR.MINOR.PATCH (semver-style):
//   • MAJOR — big/breaking changes
//   • MINOR — a new user-facing feature (e.g. the feedback toggle: 1.2 → 1.3)
//   • PATCH — small tweaks, copy/content, bug fixes (e.g. 1.3 → 1.3.1)
// For verifying a specific deploy is actually live, see the auto-generated
// commit/timestamp in lib/buildInfo.ts instead.
export const APP_VERSION = "1.3.1";
